<?php
/**
 * Site redesign (Claude Design handoff): Home, Portfolio, Project, Process, Hosting and Contact rendered from
 * templates/redesign/*.html with assets/redesign/redesign.css + redesign.js, outside Elementor.
 *
 * Preview first: while Portfolio → Settings → "Redesign live" is off, only logged-in editors see it, after
 * opening any page with ?redesign=1 (?redesign=0 switches back). Logged-in pages are never cached, so
 * visitors keep seeing the current site until it goes live.
 *
 * The .html partials are generated by the converter from the design files; keep edits in the design and re-run.
 */
defined( 'ABSPATH' ) || exit;

const DWDR_COOKIE = 'dwd_redesign';
/** Live for everyone. Set to false to put the old Elementor pages back (the redesign then needs ?redesign=1 as an editor). */
const DWDR_LIVE = true;

/** Case-study copy for every project, from the design's COPY object (templates/redesign/copy.json, written by the converter). */
function dwdr_copy() {
	static $c = null;
	if ( null === $c ) {
		$f = DWDP_DIR . 'templates/redesign/copy.json';
		$c = is_readable( $f ) ? (array) json_decode( (string) file_get_contents( $f ), true ) : array(); // phpcs:ignore
	}
	return $c;
}

/** True when this request should get the new design. */
function dwdr_on() {
	static $on = null;
	if ( null !== $on ) {
		return $on;
	}
	if ( is_admin() || wp_doing_ajax() || ( defined( 'REST_REQUEST' ) && REST_REQUEST ) ) {
		return $on = false;
	}
	if ( DWDR_LIVE || '1' === (string) get_option( 'dwdr_live', '0' ) ) {
		return $on = ! isset( $_GET['redesign'] ) || '0' !== $_GET['redesign']; // phpcs:ignore
	}
	if ( ! is_user_logged_in() || ! current_user_can( 'edit_posts' ) ) {
		return $on = false;
	}
	if ( isset( $_GET['redesign'] ) ) { // phpcs:ignore
		return $on = '1' === $_GET['redesign']; // phpcs:ignore
	}
	return $on = ! empty( $_COOKIE[ DWDR_COOKIE ] );
}

// ?redesign=1 / ?redesign=0 remembers the choice for the rest of the visit (editors only).
add_action( 'init', function () {
	if ( ! isset( $_GET['redesign'] ) || ! is_user_logged_in() || ! current_user_can( 'edit_posts' ) ) { // phpcs:ignore
		return;
	}
	$v = '1' === $_GET['redesign'] ? '1' : ''; // phpcs:ignore
	setcookie( DWDR_COOKIE, $v, $v ? time() + 30 * DAY_IN_SECONDS : time() - 3600, COOKIEPATH ?: '/', COOKIE_DOMAIN, is_ssl(), true );
	$_COOKIE[ DWDR_COOKIE ] = $v;
} );

/** Which redesigned page this request is, or ''. */
function dwdr_page() {
	if ( ! dwdr_on() ) {
		return '';
	}
	if ( is_front_page() ) {
		return 'home';
	}
	if ( is_singular( DWDP_CPT ) ) {
		return 'project';
	}
	if ( is_post_type_archive( DWDP_CPT ) || is_page( dwdp_base_slug() ) ) {
		return 'portfolio';
	}
	if ( is_singular( 'post' ) ) {
		return 'article';
	}
	if ( is_home() || is_page( 'blog' ) ) {
		return 'blog';
	}
	foreach ( array( 'process', 'hosting', 'contact', 'quote', 'thank-you', 'onboarding' ) as $slug ) {
		if ( is_page( $slug ) ) {
			return $slug;
		}
	}
	return '';
}

add_filter( 'template_include', function ( $t ) {
	return dwdr_page() ? DWDP_DIR . 'templates/redesign/layout.php' : $t;
}, 100 );

/** Read a partial and fill its placeholders. {{ key }} values are escaped; {{{ key }}} are trusted HTML. */
function dwdr_render( $name, $vars = array() ) {
	$file = DWDP_DIR . 'templates/redesign/' . $name . '.html';
	if ( ! is_readable( $file ) ) {
		return '';
	}
	$html = (string) file_get_contents( $file ); // phpcs:ignore
	$html = preg_replace_callback( '/<!--if:(\w+)-->(.*?)<!--\/if:\1-->/s', function ( $m ) use ( $vars ) {
		return empty( $vars[ $m[1] ] ) ? '' : $m[2];
	}, $html );
	$html = preg_replace_callback( '/\{\{\{ ?([\w.]+) ?\}\}\}/', function ( $m ) use ( $vars ) {
		return isset( $vars[ $m[1] ] ) ? (string) $vars[ $m[1] ] : '';
	}, $html );
	$html = preg_replace_callback( '/\{\{ ?([\w.]+) ?\}\}/', function ( $m ) use ( $vars ) {
		return isset( $vars[ $m[1] ] ) ? esc_attr( (string) $vars[ $m[1] ] ) : '';
	}, $html );
	$html = strtr( $html, array(
		'%HOME%'  => untrailingslashit( home_url() ),
		'%MEDIA%' => DWDP_URL . 'assets/redesign/media/',
		'%UPWORK_JOBS%' => false !== strpos( $html, '%UPWORK_JOBS%' ) ? dwdr_upwork_jobs() : '',
		'%YEAR%'        => current_time( 'Y' ),
		'%SHOTPLANE%'   => false !== strpos( $html, '%SHOTPLANE%' ) ? dwdr_shotplane() : '',
	) );
	return dwdr_srcset( $html );
}

/**
 * Give Media Library images in the design markup a srcset, so phones download a smaller size instead of the
 * full upload. Attachment ids are looked up once and remembered.
 */
function dwdr_srcset( $html ) {
	static $map = null;
	if ( null === $map ) {
		$map = (array) get_option( 'dwdr_att_ids', array() );
	}
	$up    = wp_get_upload_dir();
	$base  = preg_quote( $up['baseurl'], '#' );
	$dirty = false;
	$html  = preg_replace_callback( '#<img\b([^>]*?)\ssrc="(' . $base . '/[^"]+\.(?:jpe?g|png|webp))"([^>]*)>#i', function ( $m ) use ( &$map, &$dirty ) {
		if ( false !== stripos( $m[0], 'srcset=' ) ) {
			return $m[0];
		}
		$url = $m[2];
		if ( ! array_key_exists( $url, $map ) ) {
			$id = attachment_url_to_postid( preg_replace( '#-\d+x\d+(\.\w+)$#', '$1', $url ) );
			$map[ $url ] = (int) $id;
			$dirty       = true;
		}
		$id = $map[ $url ];
		if ( ! $id ) {
			return $m[0];
		}
		$set = wp_get_attachment_image_srcset( $id, 'full' );
		if ( ! $set ) {
			return $m[0];
		}
		return '<img' . $m[1] . ' src="' . $url . '" srcset="' . esc_attr( $set ) . '" sizes="(max-width: 600px) 92vw, (max-width: 980px) 90vw, 70vw"' . $m[3] . '>';
	}, $html );
	if ( $dirty ) {
		update_option( 'dwdr_att_ids', array_slice( $map, -500, null, true ), false );
	}
	return $html;
}

function dwdr_img_url( $id, $size = 'full' ) {
	$id = absint( $id );
	return $id ? (string) wp_get_attachment_image_url( $id, $size ) : '';
}

/** One project's values for the templates. */
function dwdr_project( $p ) {
	$wf = 'webflow' === dwdp_get( $p->ID, 'builder' );
	return array(
		'slug'     => $p->post_name,
		'name'     => get_the_title( $p ),
		'cat'      => (string) dwdp_get( $p->ID, 'industry' ),
		'desc'     => (string) dwdp_get( $p->ID, 'summary' ),
		'platform' => $wf ? 'Webflow' : 'WordPress',
		'cover'    => dwdr_img_url( dwdp_get( $p->ID, 'cover' ) ),
		'phone'    => dwdr_img_url( dwdp_get( $p->ID, 'mockup' ), 'large' ),
		'site'     => '1' === (string) dwdp_get( $p->ID, 'hide_link' ) ? '' : (string) dwdp_get( $p->ID, 'url' ),
		'href'     => get_permalink( $p ),
	);
}

/** The page body (between the nav and the footer for interior pages). */
function dwdr_body( $page ) {
	if ( 'portfolio' === $page ) {
		$list  = array_map( 'dwdr_project', dwdp_projects() );
		// A rebuild of a site already listed (e.g. "The Goods Vending (Webflow)") only shows under its platform filter, not in All.
		$names = wp_list_pluck( $list, 'name' );
		foreach ( $list as &$x ) {
			$base     = trim( preg_replace( '/\s*\((webflow|wordpress)\)\s*$/i', '', $x['name'] ) );
			$x['dup'] = $base !== $x['name'] && in_array( $base, $names, true );
		}
		unset( $x );
		$cards = '';
		$shown = 0;
		$copy  = dwdr_copy();
		foreach ( $list as $p ) {
			$i    = $p['dup'] ? 0 : $shown++;
			$desc = $p['desc'] ? $p['desc'] : ( $copy[ $p['slug'] ]['summary'] ?? '' );
			$card = dwdr_render( 'portfolio-card', array(
				'p.href'         => $p['href'],
				'p.mediaOrder'   => $i % 2 ? 2 : 1, // artwork and copy swap sides on every other row
				'p.copyOrder'    => $i % 2 ? 1 : 2,
				'p.cover'        => $p['cover'],
				'p.phone'        => $p['phone'],
				'p.alt'          => $p['name'] . ' website',
				'p.name'         => $p['name'],
				'p.cat'          => $p['cat'],
				'p.platform'     => $p['platform'],
				'p.platform_key' => strtolower( $p['platform'] ),
				'p.desc'         => wp_trim_words( $desc, 26 ),
				'p.num'          => sprintf( '%02d', $i + 1 ),
			) );
			// The website on the same laptop + phone mockup used before (not the design's CSS laptop).
			$card = dwdr_mockup_card( $card, $p );
			if ( $i % 2 ) {
				$card = preg_replace( '/^<a /', '<a data-flip="1" ', $card, 1 ); // text on the left: right-aligned beside the laptop
			}
			if ( $p['dup'] ) {
				$card = preg_replace( '/^<a /', '<a data-dup="1" ', $card, 1 ); // hidden in All by the stylesheet (keeps its own layout styles)
			}
			$cards .= $card;
		}
		$count = function ( $pl ) use ( $list ) {
			return count( array_filter( $list, function ( $p ) use ( $pl ) { return $p['platform'] === $pl; } ) );
		};
		$off = array( 'Bg' => 'transparent', 'Color' => '#fff', 'Border' => '#3A3A3A' );
		$on  = array( 'Bg' => '#13A6EE', 'Color' => '#fff', 'Border' => '#13A6EE' );
		$v   = array( 'cards' => $cards, 'countAll' => count( array_filter( $list, function ( $p ) { return ! $p['dup']; } ) ), 'countWP' => $count( 'WordPress' ), 'countWF' => $count( 'Webflow' ), 'isAll' => 'true', 'isWP' => 'false', 'isWF' => 'false' );
		foreach ( array( 'all' => $on, 'wp' => $off, 'wf' => $off ) as $k => $set ) {
			foreach ( $set as $prop => $val ) {
				$v[ $k . $prop ] = $val;
			}
		}
		return dwdr_render( 'portfolio', $v );
	}
	if ( 'project' === $page ) {
		$all = dwdp_projects();
		$ids = wp_list_pluck( $all, 'ID' );
		$po  = get_queried_object();
		$i   = array_search( (int) $po->ID, array_map( 'intval', $ids ), true );
		$p   = dwdr_project( $po );
		$nx  = $all ? dwdr_project( $all[ ( false === $i ? 0 : $i + 1 ) % count( $all ) ] ) : null;
		$c   = dwdr_copy();
		$cp  = isset( $c[ $p['slug'] ] ) ? $c[ $p['slug'] ] : array(
			'summary' => $p['desc'],
			'scope'   => 'Design, ' . $p['platform'] . ' build, launch, training',
			'h2a'     => 'Designed around the business',
			'p1'      => trim( $p['desc'] . ' Designed from scratch around the brand, the audience and the one thing visitors should do next.' ),
			'p2'      => 'The site was built page by page with the client approving each one before it went live, then tested on desktop, tablet and mobile before launch.',
			'h2b'     => 'Easy to keep current',
			'p3'      => 'Built on ' . $p['platform'] . ' so the owner can update text, images and pages after a one-on-one training session, with two months of support and a lifetime workmanship warranty included.',
		);
		$full = dwdr_render( 'project', array_merge( $p, $cp, array(
			'hasSite'   => '' !== $p['site'],
			'nextName'  => $nx ? $nx['name'] : '',
			'nextCat'   => $nx ? $nx['cat'] : '',
			'nextCover' => $nx ? $nx['cover'] : '',
			'nextHref'  => $nx ? $nx['href'] : home_url( '/portfolio/' ),
		) ) );
		// Keep the design's "Next project" section; the case study itself uses the two-column layout below.
		$k    = strrpos( $full, '<section' );
		$next = false === $k ? '' : substr( $full, $k );
		// Next project: shown on the same laptop + phone mockup as the portfolio.
		if ( $nx ) {
			$mock = dwdr_mockup_card( '<div class="pf-media"></div><div class="pf-copy"></div>', $nx );
			$mock = preg_replace( '#^<div class="pf-media">(.*)</div><div class="pf-copy"></div>$#s', '$1', $mock );
			$next = preg_replace( '#<div style="position:relative;overflow:hidden;border-radius:8px;aspect-ratio:16/10;background:\#1C1C1C">\s*<div style="position:absolute;inset:0">.*?</div>\s*</div>#s', str_replace( '$', '\\$', $mock ), $next, 1 );
		}
		return dwdr_case( $po, $p, $cp ) . $next;
	}
	if ( 'blog' === $page ) {
		$posts = get_posts( array( 'post_type' => 'post', 'post_status' => 'publish', 'posts_per_page' => 30 ) );
		$spans = array( 7, 5, 5, 7, 6, 6 );
		$cards = '';
		foreach ( $posts as $i => $po ) {
			$v      = dwdr_post( $po );
			$cards .= dwdr_render( 'blog-card', array( 'p.href' => $v['href'], 'p.span' => $spans[ $i % count( $spans ) ], 'p.image' => $v['image'], 'p.cat' => $v['cat'], 'p.read' => $v['read'], 'p.title' => $v['title'], 'p.excerpt' => $v['excerpt'] ) );
		}
		return dwdr_render( 'blog', array( 'cards' => $cards ) );
	}
	if ( 'article' === $page ) {
		$po   = get_queried_object();
		$v    = dwdr_post( $po );
		$all  = get_posts( array( 'post_type' => 'post', 'post_status' => 'publish', 'posts_per_page' => -1, 'fields' => 'ids' ) );
		$i    = array_search( (int) $po->ID, array_map( 'intval', $all ), true );
		$next = count( $all ) > 1 ? dwdr_post( get_post( $all[ ( false === $i ? 0 : $i + 1 ) % count( $all ) ] ) ) : null;
		$html = apply_filters( 'the_content', $po->post_content ); // phpcs:ignore
		// Halfway call to action: before the article's second heading (or at the end of a short post).
		$cta  = '<aside class="dwr-acta"><span class="dwr-eyebrow"><i></i>Need a website like this?</span><p class="dwr-acta-h">Get a flat quote for your website, usually the same day.</p><p class="dwr-acta-p">Custom design, 95+ PageSpeed, unlimited revisions. Most sites run $1,500 to $7,000.</p><div class="dwr-acta-b"><a class="dwr-pill" href="' . esc_url( home_url( '/quote/' ) ) . '">Get a Free Quote</a><a class="dwr-acta-call" href="tel:+17722101728">or call (772) 210-1728</a></div></aside>';
		$designed = dwdr_article_sections( $html );
		if ( '' === $designed ) { // no headings to build sections from: keep the simple reading layout
			$h2   = preg_match_all( '/<h2[\s>]/i', $html, $mm, PREG_OFFSET_CAPTURE ) >= 2 ? $mm[0][1][1] : -1;
			$html = $h2 > -1 ? substr_replace( $html, $cta, $h2, 0 ) : $html . $cta;
		}
		$v['image'] = (string) get_the_post_thumbnail_url( $po, 'full' ); // the hero is wide: start from the original
		$html_out = dwdr_render( 'article', array_merge( $v, array(
			'content'   => $html,
			'nextHref'  => $next ? $next['href'] : home_url( '/blog/' ),
			'nextTitle' => $next ? $next['title'] : '',
			'nextCat'   => $next ? $next['cat'] : '',
			'nextRead'  => $next ? $next['read'] : '',
			'nextImage' => $next ? $next['image'] : '',
		) ) );
		if ( '' !== $designed ) {
			// Replace the plain reading column with the designed sections; the author box becomes its own band.
			$a = strpos( $html_out, '<section data-theme="light"' );
			$b = false === $a ? false : strpos( $html_out, '</section>', $a );
			if ( false !== $b ) {
				$old    = substr( $html_out, $a, $b + 10 - $a );
				$author = '';
				if ( preg_match( '#<div data-dw-reveal="1" style="display:flex;flex-wrap:wrap;align-items:center;gap:20px;border-top:1px solid \#121212;padding-top:28px">.*</div>#s', $old, $am ) ) {
					$author = '<section data-theme="light" data-nocta="1" class="dwr-asec dwr-asec-author"><div class="dwr-ainner">' . $am[0] . '</div></section>';
				}
				$html_out = substr( $html_out, 0, $a ) . $designed . $author . substr( $html_out, $b + 10 );
			}
		}
		// The hero image spans the content column (up to 1500px): let the browser pick a size that is sharp at that width.
		return preg_replace( '#(<img data-dw-zoom="1" src="' . preg_quote( esc_attr( $v['image'] ), '#' ) . '"[^>]*?)sizes="[^"]*"#', '$1sizes="(max-width: 1500px) 100vw, 1500px"', $html_out, 1 );
	}
	if ( 'onboarding' === $page ) {
		return dwdr_onboarding();
	}
	$html = dwdr_render( $page );
	// Text-only pages get the homepage's scrolling strip of real project screenshots: at the bottom of the hero,
	// and on Process once more before the closing call to action.
	if ( in_array( $page, array( 'process', 'contact', 'thank-you' ), true ) ) {
		$i = strpos( $html, '</section>' );
		if ( false !== $i ) {
			$html = substr_replace( $html, dwdr_strip( 'dark' ), $i, 0 );
		}
	}
	if ( 'thank-you' === $page ) {
		// Book the call right here instead of waiting for a reply (name and email carried over from the form).
		$cal  = 'https://calendly.com/dreamwebdigital/dream-web-digital-consultation-call';
		$html .= '<section data-theme="light" class="dwr-calsec"><div class="dwr-calhead"><span class="dwr-eyebrow"><i></i>Skip the wait</span><h2>Pick a time for a free 30-minute Zoom.</h2><p>Grab a slot now and we’ll talk through your project. No pressure, no obligation.</p></div>'
			. '<div class="dwr-cal" data-cal="' . esc_attr( $cal ) . '"><a class="dwr-pill" href="' . esc_url( $cal ) . '" target="_blank" rel="noopener">Open my calendar</a></div></section>'
			. '<script>(function(){var w=document.querySelector(".dwr-cal");if(!w)return;var u=w.getAttribute("data-cal")+"?hide_gdpr_banner=1&primary_color=13a6ee";try{var l=JSON.parse(sessionStorage.getItem("dwr_lead")||"null");if(l){if(l.name)u+="&name="+encodeURIComponent(l.name);if(l.email)u+="&email="+encodeURIComponent(l.email);}}catch(e){}'
			. 'var f=document.createElement("iframe");f.src=u+"&embed_domain="+location.hostname+"&embed_type=Inline";f.title="Schedule a call with Michael";f.loading="lazy";w.innerHTML="";w.appendChild(f);})();</script>';
	}
	if ( 'home' === $page ) {
		$html = dwdr_intro_video( $html );
		$html = str_replace( '%SHOTPLANE%', dwdr_shotplane(), $html );
		$html = dwdr_hero_track( $html );
		// Reviews slider: one quote at a time, arrows, dots, swipe on phones.
		$html .= '<script>document.querySelectorAll(".dwr-qwrap").forEach(function(w){var g=w.querySelector(".dwr-qslider"),fs=[].slice.call(g.querySelectorAll("figure")),i=0,nav=w.nextElementSibling;function show(n){i=(n+fs.length)%fs.length;fs.forEach(function(f,k){f.classList.toggle("on",k===i);f.setAttribute("aria-hidden",k===i?"false":"true");});if(nav&&nav.classList.contains("dwr-qnav")){nav.querySelector(".dwr-qcount b").textContent=i+1;[].forEach.call(nav.querySelectorAll(".dwr-qdot"),function(d,k){d.classList.toggle("on",k===i);});}}w.addEventListener("click",function(e){var b=e.target.closest("[data-q]");if(b){show(i+(+b.getAttribute("data-q")));}});if(nav){nav.addEventListener("click",function(e){var d=e.target.closest("[data-qgo]");if(d){show(+d.getAttribute("data-qgo"));}var q=e.target.closest("[data-q]");if(q){show(i+(+q.getAttribute("data-q")));}});}var x0=null;g.addEventListener("touchstart",function(e){x0=e.touches[0].clientX;},{passive:true});g.addEventListener("touchend",function(e){if(x0===null){return;}var dx=e.changedTouches[0].clientX-x0;if(Math.abs(dx)>40){show(i+(dx<0?1:-1));}x0=null;});show(0);});</script>';
	}
	if ( 'process' === $page ) {
		$j = strrpos( $html, '<section' );
		if ( false !== $j ) {
			$band = '<section data-theme="light" class="dwr-workband"><div class="dwr-workband-h"><span class="dwr-eyebrow"><i></i>Built this way</span><a href="' . esc_url( home_url( '/portfolio/' ) ) . '">See all work <svg width="14" height="14" viewBox="0 0 14 14" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2 12 12 2M4 2h8v8"></path></svg></a></div>' . dwdr_strip( 'light', true ) . '</section>';
			$html = substr_replace( $html, $band, $j, 0 );
		}
	}
	return $html;
}

/**
 * Project case study: title, summary and details on the left (pinned while there is room), every section
 * screenshot of the site stacked on the right, the phone view after them. On phones: intro, screenshots, details.
 */
function dwdr_case( $po, $p, $cp ) {
	$id       = $po->ID;
	$sections = dwdp_ids( dwdp_get( $id, 'sections' ) );
	$mock     = absint( dwdp_get( $id, 'mockup' ) );
	$review   = trim( (string) dwdp_get( $id, 'review' ), " \"“”" );
	$by       = (string) dwdp_get( $id, 'review_by' );
	$upw      = (string) dwdp_get( $id, 'upwork_url' );
	$label    = (string) dwdp_get( $id, 'link_label' );
	$arrow    = '<svg width="14" height="14" viewBox="0 0 14 14" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2 12 12 2M4 2h8v8"></path></svg>';
	$facts    = array_filter( array(
		'Client'     => $p['name'],
		'Industry'   => $p['cat'],
		'Platform'   => $p['platform'],
		'Scope'      => $cp['scope'],
		'Responsive' => (string) dwdp_get( $id, 'responsive' ),
		'Aftercare'  => (string) dwdp_get( $id, 'aftercare' ),
	) );
	ob_start();
	?>
<section class="dwr-case" data-theme="light">
	<div class="dwr-case-grid">
		<div class="dwr-case-left" data-dwr-sticky>
			<div class="dwr-case-intro">
