/** Index just past the </div> that closes the <div> starting at $start. */
function dwdr_div_end( $h, $start ) {
	$d = 0;
	$k = $start;
	while ( true ) {
		$o  = strpos( $h, '<div', $k + 1 );
		$cl = strpos( $h, '</div>', $k + 1 );
		if ( false === $cl ) {
			return strlen( $h );
		}
		if ( false !== $o && $o < $cl ) {
			$d++;
			$k = $o;
		} elseif ( 0 === $d ) {
			return $cl + 6;
		} else {
			$d--;
			$k = $cl;
		}
	}
}

