/** The proof row (PageSpeed, Google rating, Upwork record) used under projects. */
function dwdr_proof( $slug = '' ) {
	// A project's own rating where Michael has one (Finesse: 5-star Upwork review); otherwise the Google average.
	$own = array( 'finesse-by-witney' => array( '5.0', 'Upwork review' ) );
	$r   = $own[ $slug ] ?? array( '4.9', 'Google reviews' );
	return '<div class="dwr-proof">'
		. '<span><b><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#13A6EE" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M13 2 3 14h9l-1 8 10-12h-9l1-8z"/></svg>95+</b><small>Google PageSpeed</small></span>'
		. '<span><b><i>★</i>' . $r[0] . '</b><small>' . $r[1] . '</small></span>'
		. '<span><b>100%</b><small>Job Success on Upwork</small></span>'
		. '</div>';
}


/** Faint background texture for the white quote band: 12 columns x 6 rows of real project covers (small size). */
function dwdr_shotplane() {
	$urls = array();
	foreach ( dwdp_projects() as $po ) {
		$id = (int) dwdp_get( $po->ID, 'cover' );
		$u  = $id ? wp_get_attachment_image_url( $id, 'medium' ) : '';
		if ( $u ) {
			$urls[] = $u;
		}
	}
	if ( ! $urls ) {
		return '';
	}
	$out = '';
	$n   = 0;
	for ( $c = 0; $c < 12; $c++ ) {
		$out .= '<div class="dwr-shotcol">';
		for ( $r = 0; $r < 6; $r++ ) {
			$out .= '<img class="dwr-shot-t" src="' . esc_url( $urls[ ( $n++ * 5 + $c ) % count( $urls ) ] ) . '" alt="" loading="lazy" decoding="async">';
		}
		$out .= '</div>';
	}
	return $out;
}


/**
 * Homepage hero slider: every portfolio project, in portfolio order, so new projects show up automatically.
 * Projects already in the design keep the cover picked for the slider; others use their portfolio cover.
 */
function dwdr_hero_track( $html ) {
	$i = strpos( $html, 'id="dw-hero-track"' );
	if ( false === $i ) {
		return $html;
	}
	$a = strpos( $html, '<div style="display:flex;gap:20px;padding-right:20px">', $i );
	if ( false === $a ) {
		return $html;
	}
	$end   = dwdr_div_end( $html, $i ); // the whole track
	$track = substr( $html, $a, $end - 6 - $a ); // both halves, without the track's closing </div>
	if ( ! preg_match( '#<a href="[^"]*" style="([^"]*)">\s*<img\b[^>]*?\sstyle="([^"]*)"#', $track, $st ) ) {
		return $html;
	}
	$design = array();
	if ( preg_match_all( '#<a href="[^"]*/portfolio/([^/"]+)/" style="[^"]*">\s*<img src="([^"]+)"#', $track, $mm, PREG_SET_ORDER ) ) {
		foreach ( $mm as $m ) {
			$design[ $m[1] ] = $m[2];
		}
	}
	$list  = array_map( 'dwdr_project', dwdp_projects() );
	$names = wp_list_pluck( $list, 'name' );
	$shown = array();
	foreach ( $list as $p ) {
		$base = trim( preg_replace( '/\s*\((webflow|wordpress)\)\s*$/i', '', $p['name'] ) );
		if ( $base !== $p['name'] && in_array( $base, $names, true ) ) {
			continue; // a platform rebuild of a site already in the list
		}
		$img = $design[ $p['slug'] ] ?? $p['cover'];
		if ( $img ) {
			$shown[] = $p + array( 'img' => $img );
		}
	}
	// Each site's phone mockup sits right after its own screenshot, so every project reads as one group (Michael).
	$items = '';
	foreach ( $shown as $p ) {
		$items .= '<a href="' . esc_url( $p['href'] ) . '" style="' . esc_attr( $st[1] ) . '"><img src="' . esc_url( $p['img'] ) . '" alt="' . esc_attr( $p['name'] . ' website' ) . '" style="' . esc_attr( $st[2] ) . '"></a>';
		if ( ! empty( $p['phone'] ) ) {
			$items .= '<a class="dwr-htphone" href="' . esc_url( $p['href'] ) . '" tabindex="-1"><img src="' . esc_url( $p['phone'] ) . '" alt="' . esc_attr( $p['name'] . ' website on a phone' ) . '" loading="lazy"></a>';
		}
	}
	if ( '' === $items ) {
		return $html;
	}
	$copy = str_replace( '<a href=', '<a tabindex="-1" href=', $items );
	$new  = '<div style="display:flex;gap:20px;padding-right:20px">' . $items . '</div><div style="display:flex;gap:20px;padding-right:20px" aria-hidden="true">' . $copy . '</div>';
	return substr( $html, 0, $a ) . dwdr_srcset( $new ) . substr( $html, $end - 6 );
}


